{"code": "# Boggle board
board = [
    ['A', 'B', 'R', 'L'],
    ['E', 'I', 'T', 'E'],
    ['I', 'O', 'N', 'S'],
    ['F', 'P', 'E', 'I']
]

ROWS = 4
COLS = 4

# All 8 neighbors for each cell
def get_neighbors(r, c):
    neighbors = []
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < ROWS and 0 <= nc < COLS:
                neighbors.append((nr, nc))
    return neighbors

# Find all valid Boggle words
def find_all_words(board, dictionary):
    found_words = set()

    def dfs(r, c, visited, current_word):
        current_word += board[r][c]

        # Check if current word is in dictionary
        if current_word in dictionary:
            found_words.add(current_word)

        # Try all neighbors
        for nr, nc in get_neighbors(r, c):
            if (nr, nc) not in visited:
                visited.add((nr, nc))
                dfs(nr, nc, visited, current_word)
                visited.remove((nr, nc))

    # Start from each cell
    for r in range(ROWS):
        for c in range(COLS):
            visited = {(r, c)}
            dfs(r, c, visited, "")

    return found_words

# Find all words
all_words = find_all_words(board, words)
print(f"Total valid words found: {len(all_words)}")

# Find the longest words
max_len = max(len(w) for w in all_words)
print(f"Longest word length: {max_len}")

# Get all words of max length
max_words = [w for w in all_words if len(w) == max_len]
max_words.sort()
print(f"Longest words ({len(max_words)}): {max_words}")"}

