# Let's find all paths that spell BRINIEST
def find_path_for_word(board, word):
    ROWS = len(board)
    COLS = len(board[0])

    def get_neighbors(r, c):
        neighbors = []
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < ROWS and 0 <= nc < COLS:
                    neighbors.append((nr, nc))
        return neighbors

    def dfs(r, c, visited, word_idx):
        if word_idx == len(word):
            return True, visited

        if board[r][c] != word[word_idx]:
            return False, None

        for nr, nc in get_neighbors(r, c):
            if (nr, nc) not in visited:
                visited.add((nr, nc))
                found, path = dfs(nr, nc, visited, word_idx + 1)
                if found:
                    return True, path
                visited.remove((nr, nc))

        return False, None

    # Try starting from each cell
    for r in range(ROWS):
        for c in range(COLS):
            visited = {(r, c)}
            found, path = dfs(r, c, visited, 0)
            if found:
                return path

    return None

# Verify BRINIEST
path = find_path_for_word(board, "BRINIEST")
if path:
    print(f"BRINIEST path: {path}")
    for i, (r, c) in enumerate(path):
        print(f"  Step {i}: ({r},{c}) = {board[r][c]}")
else:
