                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < ROWS and 0 <= nc < COLS:
                    neighbors.append((nr, nc))
        return neighbors

    def dfs(r, c, visited, word_idx, path):
        if word_idx == len(word):
            return True, path

        if board[r][c] != word[word_idx]:
            return False, None

        for nr, nc in get_neighbors(r, c):
            if (nr, nc) not in visited:
                visited.add((nr, nc))
                found, result_path = dfs(nr, nc, visited, word_idx + 1, path + [(nr, nc)])
                if found:
                    return True, result_path
                visited.remove((nr, nc))

        return False, None

    # Try starting from each cell
    for r in range(ROWS):
        for c in range(COLS):
            if board[r][c] == word[0]:
                visited = {(r, c)}
                found, path = dfs(r, c, visited, 1, [(r, c)])
                if found:
                    return path

    return None

